import{_ as a,c as e,o as t,ag as s}from"./chunks/framework.DPDPlp3K.js";const x=JSON.parse('{"title":"埋点为什么叫 Pixel（像素）：历史溯源","description":"","frontmatter":{},"headers":[],"relativePath":"notion/埋点为什么叫 Pixel（像素）：历史溯源.md","filePath":"notion/埋点为什么叫 Pixel（像素）：历史溯源.md"}'),l={name:"notion/埋点为什么叫 Pixel（像素）：历史溯源.md"};function o(n,i,r,h,p,d){return t(),e("div",null,i[0]||(i[0]=[s('<p>“Pixel”（像素）这个名字，源于早期互联网广告技术中一种<strong>物理上确实存在的小图片（1x1像素）</strong>。虽然现在的“Web Pixel”更多指代一段代码，但这个称呼沿用了下来，主要有三层历史和技术原因：</p><h3 id="_1-物理起源-真的是一张看不见的图" tabindex="-1">1. 物理起源：真的是一张看不见的图 <a class="header-anchor" href="#_1-物理起源-真的是一张看不见的图" aria-label="Permalink to &quot;1. 物理起源：真的是一张看不见的图&quot;">​</a></h3><p>在90年代末，最早的网站跟踪技术就是利用HTML的<code>&lt;img&gt;</code>标签加载一张<strong>尺寸为1x1像素、透明、通常为GIF格式</strong>的图片。</p><ul><li><strong>为什么用图片</strong>：浏览器加载图片时会发起一个独立的HTTP请求。这个请求会携带Cookie、浏览器信息、来源页面等数据，服务器就能记录下这次访问。</li><li><strong>为什么是1x1像素</strong>：它小到在页面上完全不可见，不会影响页面布局，也不会干扰用户视线。所以，<strong>“像素”最初指的就是这个实际存在的、被用来发起跟踪请求的微小图像文件</strong>。</li></ul><h3 id="_2-行为类比-像-像素点-一样嵌入" tabindex="-1">2. 行为类比：像“像素点”一样嵌入 <a class="header-anchor" href="#_2-行为类比-像-像素点-一样嵌入" aria-label="Permalink to &quot;2. 行为类比：像“像素点”一样嵌入&quot;">​</a></h3><p>随着技术发展，现在的“Web Pixel”不再是一张图，而是一段JavaScript代码。但“Pixel”这个叫法依然被保留，用来比喻这种跟踪机制：</p><ul><li><strong>功能上的类比</strong>：就像一幅大图（用户的行为）是由无数个像素点组成一样，单个网站的“Pixel”代码就是其中一个微小的、功能单一的数据采集点。它负责精准地捕捉用户的一次特定动作（比如“加入购物车”）。</li><li><strong>部署上的类比</strong>：它被像钉子一样“嵌入”（Embed）或“钉入”（Pin）到网页代码的特定位置，如同一个定位点，来收集该位置触发的信息。</li></ul><h3 id="_3-概念承载-从-追踪器-到-数据管道" tabindex="-1">3. 概念承载：从“追踪器”到“数据管道” <a class="header-anchor" href="#_3-概念承载-从-追踪器-到-数据管道" aria-label="Permalink to &quot;3. 概念承载：从“追踪器”到“数据管道”&quot;">​</a></h3><p>如今，尤其是像Shopify Web Pixel这样的现代技术，其形态已远不止是代码片段。它是一套标准化的数据发送和接收管道。但“Pixel”这个词作为约定俗成的行业术语，仍然被广泛使用，因为它简洁地概括了其核心功能：<strong>在用户端页面埋下一个“点”，来捕捉和传递用户行为数据</strong>。</p><p>可以说，“Pixel”这个名称，是对其最初物理形态（1x1像素图片）的历史继承，也是对它在网页上“精确定位、收集信息”功能的生动比喻。</p><p>如果还想了解这种技术具体能用来分析哪些用户行为，或者如何设置，我可以再为你详细介绍。</p><h1 id="埋点为什么叫-pixel-像素-历史溯源" tabindex="-1">埋点为什么叫 Pixel（像素）：历史溯源 <a class="header-anchor" href="#埋点为什么叫-pixel-像素-历史溯源" aria-label="Permalink to &quot;埋点为什么叫 Pixel（像素）：历史溯源&quot;">​</a></h1><h2 id="_1-起源-1×1-透明追踪像素-web-早期埋点方案" tabindex="-1">1. 起源：1×1 透明追踪像素（Web 早期埋点方案） <a class="header-anchor" href="#_1-起源-1×1-透明追踪像素-web-早期埋点方案" aria-label="Permalink to &quot;1. 起源：1×1 透明追踪像素（Web 早期埋点方案）&quot;">​</a></h2><p>早年没有 JS 埋点、Web Pixel API，统计服务商用一套极简方案： 一张 <strong>1px × 1px 完全透明的空白图片</strong>，放在页面、邮件里。</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">img</span><span style="--shiki-light:#DF8E1D;--shiki-dark:#F9E2AF;"> src</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;https://tracking.ads.com/collect?order_id=123&amp;user=xxx&quot;</span><span style="--shiki-light:#DF8E1D;--shiki-dark:#F9E2AF;"> width</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;1&quot;</span><span style="--shiki-light:#DF8E1D;--shiki-dark:#F9E2AF;"> height</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">&quot;1&quot;</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span></span></code></pre></div><ul><li>浏览器加载这张图片时，会自动带上页面信息、Cookie、参数，后端就能记录访客、转化、点击；</li><li>肉眼完全看不见，只有单个像素大小，行业直接称呼它 <strong>tracking pixel / conversion pixel</strong>（追踪像素/转化像素）。</li></ul><h2 id="_2-术语沿用至今-即使技术完全变了" tabindex="-1">2. 术语沿用至今（即使技术完全变了） <a class="header-anchor" href="#_2-术语沿用至今-即使技术完全变了" aria-label="Permalink to &quot;2. 术语沿用至今（即使技术完全变了）&quot;">​</a></h2><p>现在 Shopify、Meta、Google 的 Web Pixel 早已不再依赖 1px 图片，改用 JS 脚本、浏览器事件 API 采集数据，但术语保留了历史叫法：</p><ol><li><strong>Meta Facebook Pixel</strong>：最早普及这个命名，所有电商、广告行业跟着统一叫 Pixel；</li><li>Shopify 继承行业标准，把全站事件埋点系统命名为 Web Pixel；</li><li>业内口语简化：“装像素”=“接入埋点”，“像素事件”=“埋点事件”。</li></ol><h2 id="_3-补充区分-pixel-vs-普通埋点" tabindex="-1">3. 补充区分：Pixel vs 普通埋点 <a class="header-anchor" href="#_3-补充区分-pixel-vs-普通埋点" aria-label="Permalink to &quot;3. 补充区分：Pixel vs 普通埋点&quot;">​</a></h2><p>狭义 Pixel（广告像素）和通用埋点有细微区别：</p><ul><li><strong>Pixel</strong>：原生用于广告投放归因（统计广告带来的下单、注册转化），核心目的是广告效果结算；</li><li><strong>通用埋点</strong>：泛指所有用户行为采集（页面浏览、按钮点击、停留时长，偏产品数据分析）。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>名字来源于早年用于广告转化追踪的<strong>1px透明空白追踪图</strong>，尽管现在技术换成JS脚本，广告、电商行业依旧沿用 Pixel 代指转化埋点。</p>',24)]))}const g=a(l,[["render",o]]);export{x as __pageData,g as default};
